create table t1(a integer primary key, b);
with recursive n(i) as (select 1 union all select i+1 from n where i < 300) insert into t1(b) select 'v' || i from n;
create index t1b on t1(b);
create temp table tt(x);
attach ':memory:' as aux;
select length(ser('main'));
select deser('aux', ser('main'));
select count(*), sum(a) from aux.t1;
pragma aux.integrity_check;
insert into aux.t1(b) select b || '!' from aux.t1;
select count(*) from aux.t1;
select length(ser('aux'));
select length(ser('temp'));
select ser('nosuch') is null;
select deser('temp', x'00');
select deser('nosuch', x'00');
create table t2(z);
insert into t2 values(1),(2);
select deser('main', ser('aux'));
select count(*) from t1;
select name from sqlite_schema order by name;
pragma integrity_check;
insert into t1(b) values('after');
select count(*), max(a) from t1;
select length(ser('main')) > 0;
pragma vfs_name;
select deser('aux', x'53514c69746520666f726d6174203300');
select count(*) from aux.sqlite_schema;
